#nullable enable
using ProcessLens.Core;

namespace ProcessLens.Semantics;

/// <summary>
/// Generic evidence-first analyzer. Product-specific knowledge is optional enrichment;
/// identity, ownership and role are resolved independently so ProcessLens can explain
/// applications it has never seen before.
/// </summary>
public sealed class ProcessIntelligenceAnalyzer : IProcessAnalyzer
{
    public ProcessInsight Analyze(ProcessSnapshot process)
    {
        var identity = IdentityResolver.Resolve(process);
        var framework = FrameworkDetector.Detect(process);
        var ownership = OwnershipResolver.Resolve(process, identity, framework);
        var role = RoleClassifier.Classify(process, identity, framework, ownership);

        var evidence = new List<string>
        {
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Identità: {(identity.Evidence)}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Ambiente di esecuzione: {(framework.Evidence)}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Applicazione associata: {(ownership.Evidence)}"),
            global::ProcessLens.Core.SysPulseLocalization.Capture($"Funzione del processo: {(role.Evidence)}")
        };

        if (!string.IsNullOrWhiteSpace(process.ExecutablePath))
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Eseguibile: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(process.ExecutablePath))}"));
        if (!string.IsNullOrWhiteSpace(process.CommandLine))
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Literal("Command line disponibile per l'analisi del ruolo"));
        if (process.ChildCount > 0)
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Relazioni: {(process.ChildCount)} figli totali, {(process.SameNameChildCount)} omonimi"));
        if (process.AncestorNames.Count > 0)
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Catena padre: {(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(" <- "),process.AncestorNames.Take(6)))}"));
        if (process.ServiceDisplayNames.Count > 0)
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Servizi: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),process.ServiceDisplayNames)))}"));
        if (!string.IsNullOrWhiteSpace(process.PackageFullName))
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Package Windows: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(process.PackageFullName))}"));
        if (!string.IsNullOrWhiteSpace(process.ApplicationUserModelId))
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"AUMID Windows: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(process.ApplicationUserModelId))}"));
        if (process.IsDeepInspected)
        {
            evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Deep inspection Windows: finestra visibile={(process.HasVisibleWindow)}, TCP listen={(process.TcpListeningCount)}, TCP established={(process.TcpEstablishedCount)}, UDP={(process.UdpEndpointCount)}"));
            if (process.ModuleNames.Count > 0)
            {
                evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Moduli caricati disponibili: {(global::ProcessLens.Core.SysPulseLocalization.Opaque(process.ModuleNames.Count))}"));
                var interesting = process.ModuleNames
                    .Where(x => x.EndsWith(global::ProcessLens.Core.SysPulseLocalization.Literal(".dll"), StringComparison.OrdinalIgnoreCase))
                    .Take(12)
                    .ToArray();
                if (interesting.Length > 0)
                    evidence.Add(global::ProcessLens.Core.SysPulseLocalization.Capture($"Campione DLL osservate: {(global::ProcessLens.Core.SysPulseLocalization.Join(global::ProcessLens.Core.SysPulseLocalization.Literal(", "),interesting))}"));
            }
        }

        int overall = Weighted(identity.Confidence, ownership.Confidence, role.Confidence);
        // I punteggi sono euristici, non probabilita' statistiche.
        // Il dettaglio completo, con ID della regola, resta in Evidence.
        string evidenceKind = role.Evidence.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("--type="), StringComparison.OrdinalIgnoreCase)
            ? global::ProcessLens.Core.SysPulseLocalization.Literal("Parametri di avvio del processo")
            : role.Evidence.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("PID -> servizio"), StringComparison.OrdinalIgnoreCase)
                ? global::ProcessLens.Core.SysPulseLocalization.Literal("Associazione con un servizio Windows")
                : role.Evidence.Contains(global::ProcessLens.Core.SysPulseLocalization.Literal("flag di processo critico"), StringComparison.OrdinalIgnoreCase)
                    ? global::ProcessLens.Core.SysPulseLocalization.Literal("Informazione fornita da Windows")
                    : global::ProcessLens.Core.SysPulseLocalization.Literal("Dati del rapporto tecnico");
        string detectionBasis =
            global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Concat(global::ProcessLens.Core.SysPulseLocalization.Literal("Metodo: regole locali.\n"),global::ProcessLens.Core.SysPulseLocalization.Capture($"Fonte: {(evidenceKind)}.\n")),global::ProcessLens.Core.SysPulseLocalization.Literal("Attività in corso: non rilevata dalla classificazione."));

        return new ProcessInsight
        {
            FriendlyName = identity.FriendlyName,
            Category = role.Category,
            OwnerApp = ownership.Owner,
            Summary = role.Summary,
            Role = role.Role,
            WhatIsIt = role.Meaning,
            WhyRunning = role.WhyRunning,
            CloseImpact = role.CloseImpact,
            CloseRisk = role.CloseRisk,
            DetectionLabel = ProcessTerminology.FunctionLabel(role.Confidence),
            DetectionBasis = detectionBasis,
            ConfidencePercent = overall,
            IdentityConfidencePercent = identity.Confidence,
            OwnershipConfidencePercent = ownership.Confidence,
            RoleConfidencePercent = role.Confidence,
            Framework = framework.Name,
            ProjectRoot = null,
            Evidence = evidence.Distinct(StringComparer.OrdinalIgnoreCase).ToArray()
        };
    }

    private static int Weighted(int identity, int ownership, int role) =>
        Math.Clamp((int)Math.Round(identity * 0.25 + ownership * 0.25 + role * 0.50), 0, 100);

}
